theorem isCanonical_ext [Zero R] [BEq R] [LawfulBEq R] {p q : CPolynomial.Raw R}
    (hp : IsCanonical p) (hq : IsCanonical q) :
    equiv p q → p = q

lemma degree_eq_support_max_aux_degree [Zero R] [BEq R] [LawfulBEq R]
    (p : CPolynomial R) {k : Fin p.val.size}
    (hk : p.val.lastNonzero = some k) : p.degree = k.val

lemma degree_eq_support_max_aux_mem_support [Zero R] [BEq R] [LawfulBEq R]
    (p : CPolynomial R) {k : Fin p.val.size}
    (hk : p.val.lastNonzero = some k) : k.val ∈ p.support

theorem support_monomial [Semiring R] [DecidableEq R]
    [BEq R] [LawfulBEq R] {n : ℕ} {c : R} (hc : c ≠ 0) :
    (monomial n c).support = {n}

theorem add_mem_degreeLT {n : ℕ} {p q : CPolynomial R}
    (hp : p ∈ degreeLT (R := R) n) (hq : q ∈ degreeLT (R := R) n) :
    p + q ∈ degreeLT (R := R) n

theorem nsmul_mem_degreeLT {n m : ℕ} {p : CPolynomial R}
    (hp : p ∈ degreeLT (R := R) n) :
    m • p ∈ degreeLT (R := R) n

theorem smul_mem_degreeLT {n : ℕ} (r : R) {p : CPolynomial R}
    (hp : p ∈ degreeLT (R := R) n) :
    r • p ∈ degreeLT (R := R) n

theorem evalEval_toPoly {R : Type*} [BEq R] [LawfulBEq R] [Nontrivial R] [Semiring R]
    (x y : R) (f : CBivariate R) :
    @CBivariate.evalEval R _ _ _ _ x y f = (toPoly f).evalEval x y

theorem eval_y_horner_eq_eval_y {R : Type*}
    [Semiring R] [BEq R] [LawfulBEq R] [Nontrivial R] (a : R) (p : CBivariate R) :
    evalYHorner a p = evalY a p

theorem weight_le_natWeightedDegree_of_lt_natDegree_succ {u v n : ℕ}
    (hn : n < f.natDegree.succ) :
    u * (f.coeff n).natDegree + v * n ≤ natWeightedDegree f u v

theorem degreeLTEquiv_eq_zero_iff_eq_zero [DecidableEq R] {n : ℕ} {p : CPolynomial R}
    (hp : p ∈ degreeLT (R := R) n) :
    degreeLTEquiv (R := R) n ⟨p, hp⟩ = 0 ↔ p = 0

theorem addScaledRow_get_same [Field F] {M : DenseMatrix F}
    (hM : WellFormed M) {target source col : Nat}
    (htarget : target < M.rows) (hcol : col < M.cols) (factor : F) :
    (addScaledRow M target source factor).get target col =
      M.get target col + factor * M.get source col

theorem dotRow_addScaledRow_of_ne [Field F] {M : DenseMatrix F}
    {target source row : Nat} (factor : F) (hneq : target ≠ row) (v : Array F) :
    (addScaledRow M target source factor).dotRow row v = M.dotRow row v

theorem dotRow_scaleRow_of_ne [Field F] {M : DenseMatrix F}
    {scale row : Nat} (factor : F) (hneq : scale ≠ row) (v : Array F) :
    (scaleRow M scale factor).dotRow row v = M.dotRow row v

theorem dotRow_swapRows_left [Semiring F] {M : DenseMatrix F}
    (hM : WellFormed M) {rowA rowB : Nat} (hrowA : rowA < M.rows) (v : Array F) :
    (swapRows M rowA rowB).dotRow rowA v = M.dotRow rowB v

theorem dotRow_swapRows_right [Semiring F] {M : DenseMatrix F}
    (hM : WellFormed M) {rowA rowB : Nat} (hrowB : rowB < M.rows) (v : Array F) :
    (swapRows M rowA rowB).dotRow rowB v = M.dotRow rowA v

theorem get_setD_index_same [Zero F] {M : DenseMatrix F} {data : Array F}
    {row col : Nat} (hidx : M.index row col < data.size) (value : F) :
    (setD data (M.index row col) value).getD (M.index row col) 0 = value

theorem scaleRow_get_of_row_ne [Field F] {M : DenseMatrix F}
    {r row col : Nat} (factor : F) (hcol : col < M.cols) (hneq : r ≠ row) :
    (scaleRow M r factor).get row col = M.get row col

theorem swapRows_get_left [Zero F] {M : DenseMatrix F}
    (hM : WellFormed M) {rowA rowB col : Nat}
    (hrowA : rowA < M.rows) (hcol : col < M.cols) :
    (swapRows M rowA rowB).get rowA col = M.get rowB col

theorem swapRows_get_right [Zero F] {M : DenseMatrix F}
    (hM : WellFormed M) {rowA rowB col : Nat}
    (hrowB : rowB < M.rows) (hcol : col < M.cols) :
    (swapRows M rowA rowB).get rowB col = M.get rowA col

theorem findPivotRow_fold_none_get_eq_zero [Zero F] [BEq F] [LawfulBEq F]
    (M : DenseMatrix F) (col : Nat) {xs : List Nat}
    (h : xs.foldl (findPivotRowStep M col) none = none) {row : Nat}
    (hrow : row ∈ xs) :
    M.get row col = 0

theorem pivotColumnsBefore_mono {pivots : Array Nat} {col next : Nat}
    (h : PivotColumnsBefore pivots col) (hcol : col < next) :
    PivotColumnsBefore pivots next

theorem pivotColumnsBefore_push {pivots : Array Nat} {col next : Nat}
    (h : PivotColumnsBefore pivots col) (hcol : col < next) :
    PivotColumnsBefore (pivots.push col) next

theorem pivotColumnsStrict_getD_ne {pivots : Array Nat}
    (hstrict : PivotColumnsStrict pivots) {i j : Nat}
    (hi : i < pivots.size) (hj : j < pivots.size) (hne : i ≠ j) :
    pivots.getD i 0 ≠ pivots.getD j 0

theorem pivotColumnsStrict_push {pivots : Array Nat} {col : Nat}
    (hstrict : PivotColumnsStrict pivots) (hbefore : PivotColumnsBefore pivots col) :
    PivotColumnsStrict (pivots.push col)

theorem matrixShiftedDegreeSpecFold_acc_le
    {M : PolynomialMatrix F} {shift : Array Nat}
    (xs : List Nat) {acc : Option Nat} {a D : Nat}
    (hacc : acc = some a)
    (hfold : xs.foldl (matrixShiftedDegreeStep? M shift) acc = some D) :
    a ≤ D

theorem matrixShiftedDegreeSpecFold_exists_some_of_row
    {M : PolynomialMatrix F} {shift : Array Nat}
    (xs : List Nat) {i rowDeg : Nat}
    (hi : i ∈ xs)
    (hdeg : rowShiftedDegree? (M.getD i #[]) shift = some rowDeg) :
    ∃ D, xs.foldl (matrixShiftedDegreeStep? M shift) none = some D

theorem matrixShiftedDegreeSpecFold_some_of_acc_some
    {M : PolynomialMatrix F} {shift : Array Nat}
    (xs : List Nat) {acc : Option Nat} {a : Nat}
    (hacc : acc = some a) :
    ∃ D, xs.foldl (matrixShiftedDegreeStep? M shift) acc = some D

theorem rowCombinationTermSupport_nonempty_of_combination_degree_some
    {M : PolynomialMatrix F} {shift : Array Nat}
    (hM : WellFormed M) {coeffs : Array (CPolynomial F)} {rowDeg : Nat}
    (hdeg : rowShiftedDegree? (rowLinearCombination coeffs M) shift = some rowDeg) :
    (rowCombinationTermSupport coeffs M shift).Nonempty

lemma encode_get [Semiring F] [BEq F] [LawfulBEq F] (D : Domain F) {k : ℕ}
    (msg : Vector F k) (i : Fin D.n) :
    (encode D msg).get i = (messagePoly msg).eval (D.val[i])
